using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using DrillSim.PublicationGate;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace DrillingOperations.TrajectoryServiceTests;
[TestFixture,NonParallelizable]
public sealed class PublicationTrajectoryImportTests
{
 [Test]public async Task ImportPreservesAuthoritativeStationsAndForeignKeysBehindReceiptGate()
 {
  Guid scenario=Guid.NewGuid(),reveal=Guid.NewGuid(),id=Guid.NewGuid(),field=Guid.NewGuid(),cluster=Guid.NewGuid(),well=Guid.NewGuid(),bore=Guid.NewGuid();var receipt=new ReceiptHandler(scenario,reveal);await using var factory=new Factory(receipt);using var client=factory.CreateClient();
  using(var stage=Request(HttpMethod.Put,$"/trajectory/api/internal/publication/records/{id:D}/stage",new{scenarioId=scenario,revealId=reveal}))Assert.That((await client.SendAsync(stage)).StatusCode,Is.EqualTo(HttpStatusCode.OK));
  var payload=new{metaInfo=new{id},name="authoritative",fieldID=field,clusterID=cluster,wellID=well,wellBoreID=bore,trajectoryType="Actual",isDefinitive=true,calculationState="Completed",calculationProgress=1,mdStep=10,surveyStationList=new[]{new{abscissa=0d,md=0d,x=0d,y=0d,tvd=0d,inclination=0d,azimuth=0d},new{abscissa=10d,md=10d,x=1d,y=2d,tvd=9d,inclination=.1,azimuth=.2},new{abscissa=20d,md=20d,x=3d,y=4d,tvd=18d,inclination=.2,azimuth=.3}}};using(var import=Request(HttpMethod.Post,"/trajectory/api/internal/publication/Trajectory",payload))Assert.That((await client.SendAsync(import)).StatusCode,Is.EqualTo(HttpStatusCode.OK));
  using(var activate=Request(HttpMethod.Put,$"/trajectory/api/internal/publication/records/{id:D}/activate"))Assert.That((await client.SendAsync(activate)).StatusCode,Is.EqualTo(HttpStatusCode.OK));Assert.That((await client.GetAsync($"/trajectory/api/Trajectory/{id:D}?includeCalculatedStations=true")).StatusCode,Is.EqualTo(HttpStatusCode.NotFound));using var read=Request(HttpMethod.Get,$"/trajectory/api/Trajectory/{id:D}?includeCalculatedStations=true");using var response=await client.SendAsync(read);response.EnsureSuccessStatusCode();using var document=JsonDocument.Parse(await response.Content.ReadAsStringAsync());JsonElement root=document.RootElement;Assert.Multiple(()=>{Assert.That(P(root,"FieldID").GetGuid(),Is.EqualTo(field));Assert.That(P(root,"ClusterID").GetGuid(),Is.EqualTo(cluster));Assert.That(P(root,"WellID").GetGuid(),Is.EqualTo(well));Assert.That(P(root,"WellBoreID").GetGuid(),Is.EqualTo(bore));Assert.That(P(root,"SurveyStationList").GetArrayLength(),Is.EqualTo(3));Assert.That(P(root,"SurveyStationList")[1].GetProperty("X").GetDouble(),Is.EqualTo(1));});receipt.Committed=true;Assert.That((await client.GetAsync($"/trajectory/api/Trajectory/{id:D}?includeCalculatedStations=true")).StatusCode,Is.EqualTo(HttpStatusCode.OK));receipt.Unavailable=true;receipt.Committed=false;Assert.That((await client.GetAsync($"/trajectory/api/Trajectory/{id:D}?includeCalculatedStations=true")).StatusCode,Is.EqualTo(HttpStatusCode.OK));using var forbiddenWrite=new HttpRequestMessage(HttpMethod.Post,"/trajectory/api/Trajectory"){Content=JsonContent.Create(payload)};Assert.That((await client.SendAsync(forbiddenWrite)).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));
 }
 [Test]public async Task MissingGateCredentials_KeepExistingStagedTrajectoryHidden_AndExposeNoInternalEndpoints()
 {
  string db=Path.Combine(Path.GetTempPath(),$"trajectory-publication-missing-{Guid.NewGuid():N}.db");Guid scenario=Guid.NewGuid(),reveal=Guid.NewGuid(),id=Guid.NewGuid();var receipt=new ReceiptHandler(scenario,reveal);var payload=new{metaInfo=new{id},name="staged",fieldID=Guid.NewGuid(),clusterID=Guid.NewGuid(),wellID=Guid.NewGuid(),wellBoreID=Guid.NewGuid(),trajectoryType="Actual",isDefinitive=true,calculationState="Completed",calculationProgress=1,mdStep=10,surveyStationList=new[]{new{abscissa=0d,md=0d,x=0d,y=0d,tvd=0d,inclination=0d,azimuth=0d},new{abscissa=10d,md=10d,x=1d,y=1d,tvd=9d,inclination=.1,azimuth=.2},new{abscissa=20d,md=20d,x=2d,y=2d,tvd=18d,inclination=.2,azimuth=.3}}};await using(var configured=new Factory(receipt,db,true)){using var client=configured.CreateClient();using(var stage=Request(HttpMethod.Put,$"/trajectory/api/internal/publication/records/{id:D}/stage",new{scenarioId=scenario,revealId=reveal}))(await client.SendAsync(stage)).EnsureSuccessStatusCode();using(var import=Request(HttpMethod.Post,"/trajectory/api/internal/publication/Trajectory",payload))(await client.SendAsync(import)).EnsureSuccessStatusCode();}await using(var missing=new Factory(receipt,db,false)){using var client=missing.CreateClient();Assert.That((await client.GetAsync($"/trajectory/api/Trajectory/{id:D}?includeCalculatedStations=true")).StatusCode,Is.EqualTo(HttpStatusCode.NotFound));using var internalRead=Request(HttpMethod.Get,$"/trajectory/api/internal/publication/records/{id:D}");Assert.That((await client.SendAsync(internalRead)).StatusCode,Is.EqualTo(HttpStatusCode.NotFound));}Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
 }
 static JsonElement P(JsonElement value,string name)=>value.EnumerateObject().First(x=>x.Name.Equals(name,StringComparison.OrdinalIgnoreCase)).Value;
 static HttpRequestMessage Request(HttpMethod method,string path,object? body=null){var request=new HttpRequestMessage(method,path);request.Headers.Add("X-DrillSim-Publication-Key",Factory.Key);if(body is not null)request.Content=JsonContent.Create(body);return request;}
 sealed class Factory(ReceiptHandler receipt,string? database=null,bool configureGate=true):WebApplicationFactory<global::Program>{internal const string Key="publication-import-test-key";readonly string db=database??Path.Combine(Path.GetTempPath(),$"trajectory-publication-{Guid.NewGuid():N}.db");protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseSetting("ConnectionStrings:Sqlite",$"Data Source={db}");builder.UseSetting("DRILLSIM_PUBLICATION_IMPORT_KEY",configureGate?Key:string.Empty);builder.UseSetting("AnalysisApiUrl",configureGate?"http://analysis.test/":string.Empty);if(configureGate)builder.ConfigureServices(services=>{services.RemoveAll<ScenarioPublicationGateStore>();services.AddSingleton(new ScenarioPublicationGateStore(ScenarioPublicationGateExtensions.DeriveGateConnection($"Data Source={db}"),new HttpClient(receipt){BaseAddress=new Uri("http://analysis.test/")}));});}protected override void Dispose(bool disposing){base.Dispose(disposing);Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();}}
 sealed class ReceiptHandler(Guid scenario,Guid reveal):HttpMessageHandler{internal bool Committed;internal bool Unavailable;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>Task.FromResult(new HttpResponseMessage(Unavailable?HttpStatusCode.ServiceUnavailable:Committed?HttpStatusCode.OK:HttpStatusCode.NotFound){Content=JsonContent.Create(new{scenarioId=scenario,revealId=reveal,status="Revealed"})});}
}

